import json
from dataclasses import dataclass
from typing import Iterator, Optional, Dict, Any
import io

@dataclass(frozen=True)
class TransactionRecord:
    id: str
    amount: float
    timestamp: str
    status: str

def parse_record(raw_line: str) -> Optional[TransactionRecord]:
    try:
        data = json.loads(raw_line.strip())
        # Validacion de tipos estricta
        return TransactionRecord(
            id=str(data["id"]),
            amount=float(data["amount"]),
            timestamp=str(data["timestamp"]),
            status=str(data["status"])
        )
    except (json.JSONDecodeError, KeyError, ValueError) as err:
        # Excepcion controlada: no colapsar el pipeline por un registro danado
        return None

def stream_transactions(stream: io.StringIO) -> Iterator[TransactionRecord]:
    for line_num, line in enumerate(stream, start=1):
        if not line.strip():
            continue
        record = parse_record(line)
        if record is not None:
            yield record

